import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as memberRepo from "@/server/repositories/member-repository";
import * as memberService from "@/server/services/member-service";
import * as svc from "@/server/services/api-token-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import { registerEventHandlers } from "@/server/services/event-registry";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("tmp", () => {
  it("works", async () => {
    const t = await createTenant("tok", "growth");
    const a = t.actors.member;
    const created = [];
    for (let i = 0; i < 5; i++) created.push(await svc.createApiToken(a, { orgId: t.org.id, name: ` t${i} `, scope: "write", expiresInDays: 1 }));
    await expect(svc.createApiToken(a, { orgId: t.org.id, name: "x", scope: "read", expiresInDays: 1 })).rejects.toThrow();
    await expect(svc.createApiToken(t.actors.viewer, { orgId: t.org.id, name: "x", scope: "write", expiresInDays: 1 })).rejects.toThrow();
    const list = await svc.listApiTokens(a, t.org.id);
    expect(list.map((x) => x.name)).toEqual(["t4", "t3", "t2", "t1", "t0"]);
    const actor = await svc.authenticateApiToken(created[0]!.token);
    expect(actor).toMatchObject({ role: "member", userId: a.userId });
    expect((await svc.listApiTokens(a, t.org.id)).at(-1)!.lastUsedAt).not.toBeNull();
    await svc.revokeApiToken(a, t.org.id, created[0]!.apiToken.id);
    expect(await svc.authenticateApiToken(created[0]!.token)).toBeNull();
    const m = await memberRepo.findMember(t.org.id, a.userId);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m!.id });
    const after = await svc.listApiTokens(t.actors.owner, t.org.id, a.userId);
    expect(after.every((x) => x.revokedAt)).toBe(true);
    const page = await activityRepo.listActivity({ orgId: t.org.id, action: ["api_token.created", "api_token.revoked"], limit: 100, cursor: null } as never);
    console.log(page.items.map((e) => [e.action, e.actorId === t.actors.owner.userId, e.subjectKind]));
    expect(page.items.length).toBe(10);
  });
});
